<div class="cr-section"><h3>Vehicle / Equipment Identity</h3><div class="form-grid"><div class="form-group"><label>Name <span class="required">*</span></label><input name="name" required placeholder="e.g. JCB 3DX / Tata 407" value="<?= $e($data['name'] ?? '') ?>"></div><div class="form-group"><label>Make</label><input name="make" placeholder="e.g. Tata, Mahindra, JCB" value="<?= $e($data['make'] ?? '') ?>"></div><div class="form-group"><label>Model</label><input name="model" value="<?= $e($data['model'] ?? '') ?>"></div><div class="form-group"><label>Model Year</label><input type="number" min="1900" max="<?= date('Y')+1 ?>" name="model_year" value="<?= $e($data['model_year'] ?? '') ?>"></div><div class="form-group"><label>Fuel Type</label><select name="fuel_type"><option value="">Select fuel</option><?php foreach(['Diesel','Petrol','CNG','Electric','Hybrid','Other'] as $v): ?><option <?= ($data['fuel_type']??'')===$v?'selected':'' ?>><?= $e($v) ?></option><?php endforeach; ?></select></div><div class="form-group"><label>Body / Equipment Type</label><input name="body_type" placeholder="e.g. Tipper, Flatbed, Excavator" value="<?= $e($data['body_type'] ?? '') ?>"></div><div class="form-group"><label>Registration No.</label><input name="registration_no" placeholder="e.g. MN-01-AB-1234" value="<?= $e($data['registration_no'] ?? '') ?>"></div><div class="form-group"><label>Capacity</label><input name="capacity" placeholder="e.g. 1 ton / 5 cubic metre" value="<?= $e($data['capacity'] ?? '') ?>"></div><div class="form-group"><label>Seating Capacity</label><input type="number" min="0" name="seating_capacity" value="<?= $e($data['seating_capacity'] ?? '') ?>"></div><div class="form-group"><label>Engine / Power</label><input name="engine_power" placeholder="e.g. 55 HP" value="<?= $e($data['engine_power'] ?? '') ?>"></div><div class="form-group"><label>Ownership</label><select name="ownership_type"><?php foreach(['OWNER'=>'Owner','LEASED'=>'Leased','PARTNER'=>'Partner','OTHER'=>'Other'] as $v=>$label): ?><option value="<?= $v ?>" <?= ($data['ownership_type']??'OWNER')===$v?'selected':'' ?>><?= $label ?></option><?php endforeach; ?></select></div><div class="form-group"><label>Condition</label><select name="condition_status"><?php foreach(['NEW'=>'New','GOOD'=>'Good','FAIR'=>'Fair','NEEDS_SERVICE'=>'Needs Service'] as $v=>$label): ?><option value="<?= $v ?>" <?= ($data['condition_status']??'GOOD')===$v?'selected':'' ?>><?= $label ?></option><?php endforeach; ?></select></div></div></div>
